B.Tw=new A.bj("P0122","Throttle/pedal position sensor/switch A circuit low","Throttle position sensor A reported voltage below the minimum calibrated threshold.",B.Nn,B.Oj)
B.PR=s(["Exhaust leak upstream of sensor","O2 sensor wiring or element issue","Fuel trim fault"],t.s)
